using System;
using CargoWise.RefDbRepo.Staging.Schema_New;
using NUnit.Framework;

namespace CargoWise.RefDbRepo.Staging.eHubMessageDownloader.Test
{
	[TestFixture]
	class GMDMessageCreatorFixture
	{
		[TestCase(MessageGenericSGText, ContentGenericSGText, "SG", "CLASET", TestName = "Create SG GMD")]
		[TestCase(MessageGenericERText, ContentGenericERText, "ER", "IFTRIN", TestName = "Create ER GMD")]
		public void Create(string messageText, string contentText, string source, string subSource)
		{
			var utcNow = DateTime.UtcNow;
			var message = new GMDMessageCreator().GetSourceDataFromStreamText(messageText, sourceData);
			Assert.That(message.SDA_Filetype, Is.EqualTo(DataSourceConstants.FileType.TXT.ToString()));
			Assert.That(message.SDA_Source, Is.EqualTo(source));
			Assert.That(message.SDA_ContentText, Is.EqualTo(contentText));
			Assert.That(message.SDA_ContentType, Is.EqualTo(DataSourceConstants.ContentType.Edifact));
			Assert.That(message.SDA_SourceTime, Is.GreaterThanOrEqualTo(utcNow));
			Assert.That(message.SDA_SubSource, Is.EqualTo(subSource));
			Assert.That(message.IsSourceDataQueuedStatus());
		}

		[Test]
		public void CreateMissingRefDataRepoMessage()
		{
			sourceData.SDA_ContentText = MessageMissingRefDataRepoMessage;
			var message = new GMDMessageCreator().GetSourceDataFromStreamText(MessageMissingRefDataRepoMessage, sourceData);
			Assert.That(message.SDA_Filetype, Is.EqualTo(DataSourceConstants.FileType.TXT.ToString()));
			Assert.That(message.SDA_Source, Is.EqualTo(Constants.SourceError));
			Assert.That(message.SDA_ContentText, Is.EqualTo(MessageMissingRefDataRepoMessage));
			Assert.IsNull(message.SDA_ContentType);
			Assert.IsNull(message.SDA_SourceTime);
			Assert.That(message.SDA_SubSource, Is.EqualTo(Constants.SubSourceUnknown));
			Assert.That(message.IsSourceDataErrorStatus());
		}

		[Test]
		public void CreateMissingSource()
		{
			sourceData.SDA_ContentText = MessageMissingSource;
			var message = new GMDMessageCreator().GetSourceDataFromStreamText(MessageMissingSource, sourceData);
			Assert.That(message.SDA_Filetype, Is.EqualTo(DataSourceConstants.FileType.TXT.ToString()));
			Assert.That(message.SDA_Source, Is.EqualTo(Constants.SourceError));
			Assert.That(message.SDA_ContentText, Is.EqualTo(MessageMissingSource));
			Assert.That(message.SDA_ContentType, Is.EqualTo(DataSourceConstants.ContentType.Edifact));
			Assert.IsNull(message.SDA_SourceTime);
			Assert.That(message.SDA_SubSource, Is.EqualTo("CLASET"));
			Assert.That(message.IsSourceDataErrorStatus());
		}

		[Test]
		public void CreateMissingSubSource()
		{
			sourceData.SDA_ContentText = MessageMissingSubSource;
			var message = new GMDMessageCreator().GetSourceDataFromStreamText(MessageMissingSubSource, sourceData);
			Assert.That(message.SDA_Filetype, Is.EqualTo(DataSourceConstants.FileType.TXT.ToString()));
			Assert.That(message.SDA_Source, Is.EqualTo("SG"));
			Assert.That(message.SDA_ContentText, Is.EqualTo(MessageMissingSubSource));
			Assert.That(message.SDA_ContentType, Is.EqualTo(DataSourceConstants.ContentType.Edifact));
			Assert.IsNull(message.SDA_SourceTime);
			Assert.That(message.SDA_SubSource, Is.EqualTo(Constants.SubSourceUnknown));
			Assert.That(message.IsSourceDataErrorStatus());
		}

		[Test]
		public void CreateMissingContentType()
		{
			sourceData.SDA_ContentText = MessageMissingContentType;
			var message = new GMDMessageCreator().GetSourceDataFromStreamText(MessageMissingContentType, sourceData);
			Assert.That(message.SDA_Filetype, Is.EqualTo(DataSourceConstants.FileType.TXT.ToString()));
			Assert.That(message.SDA_Source, Is.EqualTo("SG"));
			Assert.That(message.SDA_ContentText, Is.EqualTo(MessageMissingContentType));
			Assert.IsNull(message.SDA_ContentType);
			Assert.IsNull(message.SDA_SourceTime);
			Assert.That(message.SDA_SubSource, Is.EqualTo("CLASET"));
			Assert.That(message.IsSourceDataErrorStatus());
		}

		[Test]
		public void CreateMissingContentText()
		{
			sourceData.SDA_ContentText = MessageMissingContentText;
			var message = new GMDMessageCreator().GetSourceDataFromStreamText(MessageMissingContentText, sourceData);
			Assert.That(message.SDA_Filetype, Is.EqualTo(DataSourceConstants.FileType.TXT.ToString()));
			Assert.That(message.SDA_Source, Is.EqualTo("SG"));
			Assert.That(message.SDA_ContentText, Is.EqualTo(MessageMissingContentText));
			Assert.That(message.SDA_ContentType, Is.EqualTo(DataSourceConstants.ContentType.Edifact));
			Assert.IsNull(message.SDA_SourceTime);
			Assert.That(message.SDA_SubSource, Is.EqualTo("CLASET"));
			Assert.That(message.IsSourceDataErrorStatus());
		}

